using System.ComponentModel;
using System.Text.Json;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var apiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set the OPENAI_API_KEY environment variable before running.");

var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearcher = new WebSearcher();

var tools = new AIFunction[]
{
    AIFunctionFactory.Create(webSearcher.SearchAsync),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Build the chat client with automatic tool invocation
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(apiKey)
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a research agent. Your job is to research a topic provided by the
    user by searching the web, taking notes on key findings, and then producing
    a concise summary.

    Workflow:
    1. Break the topic into 2-3 search queries.
    2. For each query, call the SearchWeb tool.
    3. After each search, call AddNote to record the most important facts.
    4. After all searches, call GetNotes to review your notes.
    5. Produce a well-organized summary with citations.

    Always use the tools — do not fabricate search results.
    """;

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════════╗");
Console.WriteLine("║        Research Agent (MEAI + OpenAI)    ║");
Console.WriteLine("╚══════════════════════════════════════════╝");
Console.WriteLine();
Console.WriteLine("Enter a topic to research (or 'quit' to exit):");

while (true)
{
    Console.Write("\n> ");
    var topic = Console.ReadLine()?.Trim();
    if (string.IsNullOrEmpty(topic) || topic.Equals("quit", StringComparison.OrdinalIgnoreCase))
        break;

    notebook.Clear();

    List<ChatMessage> messages =
    [
        new(ChatRole.System, SystemPrompt),
        new(ChatRole.User, $"Research the following topic and summarize your findings:\n\n{topic}"),
    ];

    Console.WriteLine("\n🔍 Researching...\n");

    var response = await client.GetResponseAsync(messages, chatOptions);

    Console.WriteLine("═══════════════════ Summary ═══════════════════");
    Console.WriteLine(response.Text);
    Console.WriteLine("═══════════════════════════════════════════════\n");
}

Console.WriteLine("Goodbye!");

