/// <summary>Performs web searches via the Brave Search API or a fallback DuckDuckGo scrape.</summary>
sealed class WebSearcher
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders = { { "User-Agent", "ResearchAgent/1.0" } },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for information on a query. Returns a list of result snippets.")]
    public async Task<string> SearchAsync(
        [Description("The search query to look up on the web")] string query)
    {
        Console.WriteLine($"  🌐 Searching: \"{query}\"");

        try
        {
            // Try Brave Search API if a key is available
            var braveKey = Environment.GetEnvironmentVariable("BRAVE_API_KEY");
            if (!string.IsNullOrEmpty(braveKey))
                return await BraveSearchAsync(query, braveKey);

            // Fallback: DuckDuckGo instant-answer API (no key required)
            return await DuckDuckGoSearchAsync(query);
        }
        catch (Exception ex)
        {
            return $"Search failed: {ex.Message}";
        }
    }

    private static async Task<string> BraveSearchAsync(string query, string apiKey)
    {
        var url = $"https://api.search.brave.com/res/v1/web/search?q={Uri.EscapeDataString(query)}&count=5";
        using var request = new HttpRequestMessage(HttpMethod.Get, url);
        request.Headers.Add("X-Subscription-Token", apiKey);
        request.Headers.Add("Accept", "application/json");

        using var response = await Http.SendAsync(request);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var results = new List<string>();

        if (doc.RootElement.TryGetProperty("web", out var web) &&
            web.TryGetProperty("results", out var items))
        {
            foreach (var item in items.EnumerateArray().Take(5))
            {
                var title = item.GetProperty("title").GetString();
                var snippet = item.TryGetProperty("description", out var d) ? d.GetString() : "";
                var itemUrl = item.GetProperty("url").GetString();
                results.Add($"- {title}: {snippet} ({itemUrl})");
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : "No results found.";
    }

    private static async Task<string> DuckDuckGoSearchAsync(string query)
    {
        var url = $"https://api.duckduckgo.com/?q={Uri.EscapeDataString(query)}&format=json&no_html=1";
        using var response = await Http.GetAsync(url);
        response.EnsureSuccessStatusCode();

        using var doc = JsonDocument.Parse(await response.Content.ReadAsStringAsync());
        var results = new List<string>();

        // Abstract / instant answer
        var abs = doc.RootElement.GetProperty("Abstract").GetString();
        if (!string.IsNullOrWhiteSpace(abs))
        {
            var src = doc.RootElement.GetProperty("AbstractURL").GetString();
            results.Add($"- {abs} ({src})");
        }

        // Related topics
        if (doc.RootElement.TryGetProperty("RelatedTopics", out var topics))
        {
            foreach (var t in topics.EnumerateArray().Take(5))
            {
                if (t.TryGetProperty("Text", out var text) &&
                    t.TryGetProperty("FirstURL", out var furl))
                {
                    results.Add($"- {text.GetString()} ({furl.GetString()})");
                }
            }
        }

        return results.Count > 0
            ? string.Join("\n", results)
            : "No results found via DuckDuckGo instant answers. Try a more specific query.";
    }
}

/// <summary>Simple note-taking tool that stores research notes in memory.</summary>
sealed class Notebook
{
    private readonly List<string> _notes = [];

    [Description("Save a research note. Use this to record key facts or findings.")]
    public string AddNote(
        [Description("The note text to save")] string note)
    {
        _notes.Add(note);
        Console.WriteLine($"  📝 Note #{_notes.Count} saved");
        return $"Note #{_notes.Count} saved.";
    }

    [Description("Retrieve all saved research notes.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        Console.WriteLine($"  📋 Retrieving {_notes.Count} note(s)");
        return string.Join("\n", _notes.Select((n, i) => $"[{i + 1}] {n}"));
    }

    public void Clear() => _notes.Clear();
}

